/* SUPREME 1:1 CENTER HEADER SEARCH CONTROLLER */
window.searchToggle = function (btn, evt) {
  if (evt) {
    evt.preventDefault();
    evt.stopPropagation();
  }
  var searchMainBox = $(btn).closest('.search_main_box');
  if (!searchMainBox.length) return;

  if (searchMainBox.hasClass('active')) {
    searchMainBox.removeClass('active');
    searchMainBox.find('.header_search_input').val('').blur();
  } else {
    searchMainBox.addClass('active');
    setTimeout(function() {
      searchMainBox.find('.header_search_input').focus();
    }, 100);
  }
};

window.handleHeaderSearch = function (evt, inputEl) {
  if (evt.key === 'Enter') {
    window.executeHeaderSearch(inputEl);
  } else if (evt.key === 'Escape') {
    var searchMainBox = $(inputEl).closest('.search_main_box');
    searchMainBox.removeClass('active');
    $(inputEl).blur();
  }
};

window.executeHeaderSearch = function (triggerEl) {
  var searchMainBox = $(triggerEl).closest('.search_main_box');
  var input = searchMainBox.find('.header_search_input');
  var query = $.trim(input.val());
  if (query) {
    window.location.href = 'products.html?search=' + encodeURIComponent(query);
  }
};

$(document).on('click', function (e) {
  if (!$(e.target).closest('.search_main_box').length) {
    $('.search_main_box.active').removeClass('active');
  }
});

/* MOBILE SIDEBAR & HAMBURGER TOGGLE CONTROLLER */
$(document).ready(function() {
    // 1. Mobile Hamburger Toggle
    $('#nav-icon3').off('click').on('click', function(e) {
        e.stopPropagation();
        $(this).toggleClass('open');
        $('.sidebar_wrap').toggleClass('open');
        $('body').toggleClass('overflow-hidden');
    });

    // 2. Mobile Accordion Dropdown
    $('.sidebar_wrap .dropdown-toggle').off('click').on('click', function(e) {
        e.preventDefault();
        e.stopPropagation();
        var $parent = $(this).closest('.dropdown');
        $parent.toggleClass('open');
    });

    // 3. Close Drawer on Nav Link Click (only leaf links)
    $('.sidebar_wrap .links a:not(.dropdown-toggle)').on('click', function() {
        $('#nav-icon3').removeClass('open');
        $('.sidebar_wrap').removeClass('open');
        $('body').removeClass('overflow-hidden');
    });

    // 4. Close Drawer on Outside Tap
    $(document).on('click', function(e) {
        if (!$(e.target).closest('.sidebar_wrap, #nav-icon3').length) {
            $('#nav-icon3').removeClass('open');
            $('.sidebar_wrap').removeClass('open');
            $('body').removeClass('overflow-hidden');
        }
        // Also close search if tapping outside
        if (!$(e.target).closest('.search_main_box').length) {
            $('.search_main_box').removeClass('active');
        }
    });

    // 5. Close search / menu on Escape key
    $(document).on('keydown', function(e) {
        if (e.key === 'Escape') {
            $('#nav-icon3').removeClass('open');
            $('.sidebar_wrap').removeClass('open');
            $('body').removeClass('overflow-hidden');
            $('.search_main_box').removeClass('active');
        }
    });

    // 6. Scroll to top handler
    $('#scroll_btn, .scollTop').off('click').on('click', function(e) {
        e.preventDefault();
        $('html, body').animate({ scrollTop: 0 }, 500);
    });
});
